"""Surrounded Regions — flip everything except regions touching the border.

Mark border-connected 'O's first; whatever is left is enclosed.

Time: O(m*n)   Space: O(m*n)
"""
from typing import List


class Solution:
    def solve(self, board: List[List[str]]) -> None:
        if not board or not board[0]:
            return
        m, n = len(board), len(board[0])

        def mark(i: int, j: int) -> None:
            stack = [(i, j)]
            while stack:
                x, y = stack.pop()
                if 0 <= x < m and 0 <= y < n and board[x][y] == "O":
                    board[x][y] = "#"
                    stack.extend(((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)))

        for i in range(m):
            mark(i, 0)
            mark(i, n - 1)
        for j in range(n):
            mark(0, j)
            mark(m - 1, j)

        for i in range(m):
            for j in range(n):
                board[i][j] = "O" if board[i][j] == "#" else "X"
